[data-rsbs-overlay] {
    background: #fff;
    background: var(--rsbs-bg, #fff);
    border-top-left-radius: 16px;
    border-top-left-radius: var(--rsbs-overlay-rounded, 16px);
    border-top-right-radius: 16px;
    border-top-right-radius: var(--rsbs-overlay-rounded, 16px);
    flex-direction: column;
    height: 0;
    height: var(--rsbs-overlay-h, 0);
    transform: translateZ(0);
    transform: translate3d(0, var(--rsbs-overlay-translate-y, 0), 0);
    will-change: height
}

[data-rsbs-overlay]:focus {
    outline: none
}

[data-rsbs-is-blocking=false] [data-rsbs-overlay] {
    box-shadow: 0 -5px 60px 0 #2659731c, 0 -1px 0 #2659730d
}

[data-rsbs-overlay],
[data-rsbs-root]:after {
    margin-left: env(safe-area-inset-left);
    margin-left: var(--rsbs-ml, env(safe-area-inset-left));
    margin-right: env(safe-area-inset-right);
    margin-right: var(--rsbs-mr, env(safe-area-inset-right));
    max-width: auto;
    max-width: var(--rsbs-max-w, auto)
}

[data-rsbs-backdrop],
[data-rsbs-overlay],
[data-rsbs-root]:after {
    -ms-scroll-chaining: none;
    -webkit-tap-highlight-color: transparent;
    -webkit-touch-callout: none;
    bottom: 0;
    left: 0;
    overscroll-behavior: none;
    position: fixed;
    right: 0;
    touch-action: none;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    z-index: 3
}

[data-rsbs-backdrop] {
    background-color: #0009;
    background-color: var(--rsbs-backdrop-bg, #0009);
    bottom: -60px;
    cursor: pointer;
    opacity: 1;
    top: -60px;
    will-change: opacity
}

[data-rsbs-is-dismissable=false] [data-rsbs-backdrop] {
    cursor: ns-resize
}

[data-rsbs-root]:after {
    background: #fff;
    background: var(--rsbs-bg, #fff);
    content: "";
    height: 1px;
    pointer-events: none;
    transform: scaleY(0);
    transform: scaleY(var(--rsbs-antigap-scale-y, 0));
    transform-origin: bottom;
    will-change: transform
}

[data-rsbs-footer],
[data-rsbs-header] {
    cursor: ns-resize;
    flex-shrink: 0;
    padding: 16px
}

[data-rsbs-header] {
    box-shadow: 0 1px 0 rgba(46, 59, 66, .125);
    box-shadow: 0 1px 0 rgba(46, 59, 66, calc(var(--rsbs-content-opacity, 1)*.125));
    padding-bottom: 8px;
    padding-top: calc(20px + env(safe-area-inset-top));
    text-align: center;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    z-index: 1
}

[data-rsbs-header]:before {
    background-color: #00000024;
    background-color: var(--rsbs-handle-bg, #00000024);
    border-radius: 2px;
    content: "";
    display: block;
    height: 4px;
    left: 50%;
    position: absolute;
    top: calc(8px + env(safe-area-inset-top));
    transform: translateX(-50%);
    width: 36px
}

@media (-webkit-min-device-pixel-ratio:2),
(min-resolution:2dppx) {
    [data-rsbs-header]:before {
        transform: translateX(-50%) scaleY(.75)
    }
}

[data-rsbs-has-header=false] [data-rsbs-header] {
    box-shadow: none;
    padding-top: calc(12px + env(safe-area-inset-top))
}

[data-rsbs-scroll] {
    -webkit-tap-highlight-color: revert;
    -webkit-touch-callout: revert;
    -ms-scroll-chaining: none;
    -webkit-overflow-scrolling: touch;
    flex-grow: 1;
    flex-shrink: 1;
    overflow: auto;
    overscroll-behavior: contain;
    -webkit-user-select: auto;
    -ms-user-select: auto;
    -moz-user-select: auto;
    user-select: auto
}

[data-rsbs-scroll]:focus {
    outline: none
}

[data-rsbs-has-footer=false] [data-rsbs-content] {
    padding-bottom: env(safe-area-inset-bottom)
}

[data-rsbs-content] {
    overflow: hidden
}

[data-rsbs-footer] {
    box-shadow: 0 -1px 0 rgba(46, 59, 66, .125), 0 2px 0 #fff;
    box-shadow: 0 -1px 0 rgba(46, 59, 66, calc(var(--rsbs-content-opacity, 1)*.125)), 0 2px 0 var(--rsbs-bg, #fff);
    overflow: hidden;
    padding-bottom: calc(16px + env(safe-area-inset-bottom));
    z-index: 1
}

[data-rsbs-is-dismissable=false][data-rsbs-state=closing] [data-rsbs-footer]>*,
[data-rsbs-is-dismissable=false][data-rsbs-state=closing] [data-rsbs-header]>*,
[data-rsbs-is-dismissable=false][data-rsbs-state=closing] [data-rsbs-scroll]>*,
[data-rsbs-is-dismissable=false][data-rsbs-state=opening] [data-rsbs-footer]>*,
[data-rsbs-is-dismissable=false][data-rsbs-state=opening] [data-rsbs-header]>*,
[data-rsbs-is-dismissable=false][data-rsbs-state=opening] [data-rsbs-scroll]>*,
[data-rsbs-is-dismissable=true] [data-rsbs-footer]>*,
[data-rsbs-is-dismissable=true] [data-rsbs-header]>*,
[data-rsbs-is-dismissable=true] [data-rsbs-scroll]>* {
    opacity: 1;
    opacity: var(--rsbs-content-opacity, 1)
}

[data-rsbs-is-dismissable=false][data-rsbs-state=closing] [data-rsbs-backdrop],
[data-rsbs-is-dismissable=false][data-rsbs-state=opening] [data-rsbs-backdrop],
[data-rsbs-is-dismissable=true] [data-rsbs-backdrop] {
    opacity: 1;
    opacity: var(--rsbs-backdrop-opacity, 1)
}

[data-rsbs-state=closed],
[data-rsbs-state=closing] {
    pointer-events: none
}

.rc-slider {
