    border-color: #96dbfa;
    box-shadow: none
}

.rc-slider-handle:hover {
    border-color: #57c5f7
}

.rc-slider-handle:active {
    border-color: #57c5f7;
    box-shadow: 0 0 5px #57c5f7;
