.load6 .loader {
    animation: load6 1.7s ease infinite;
    border-radius: 50%;
    color: #fff;
    font-size: 90px;
    height: 1em;
    margin: 72px auto;
    overflow: hidden;
    position: relative;
    text-indent: -9999em;
    transform: translateZ(0);
    width: 1em
}

@keyframes load6 {
    0% {
        box-shadow: 0 -.83em 0 -.4em, 0 -.83em 0 -.42em, 0 -.83em 0 -.44em, 0 -.83em 0 -.46em, 0 -.83em 0 -.477em;
        transform: rotate(0deg)
    }

    5%,
    95% {
        box-shadow: 0 -.83em 0 -.4em, 0 -.83em 0 -.42em, 0 -.83em 0 -.44em, 0 -.83em 0 -.46em, 0 -.83em 0 -.477em
    }

    10%,
