    position: relative
}

.tb--sidebar-submenu:after {
    content: "";
    display: inline-block;
    height: 100%;
    left: 0;
    position: absolute;
    top: 0;
    width: 100%
}

.tb--sidebar-submenu .tb--sidebar-submenu_link {
    font-size: 14px;
    padding: 12px 16px;
    position: relative;
    z-index: 2
}

.tb--sidebar-submenu span {
    z-index: 2
}

.tb--sidebar-submenu i {
    font-size: 24px
}

.tb--sidebar-submenu_item {
    position: relative;
    z-index: 2
}

.tb--sidebar-submenu_item:hover:after {
    background-color: var(--background-color-1);
    background-image: var(--background-gradient-1);
    content: "";
    display: inline-block;
    height: 100%;
    left: 0;
    opacity: .3;
    position: absolute;
    top: 0;
    width: 100%
}

.tb--sidebar-submen_open {
    position: relative
}

@media screen and (min-width:1024px) {
    .tb--sidebar-submen_open:before {
        display: none
    }
}

.sidebar--footer {
    background-color: var(--background-color-3);
    background-image: var(--background-gradient-3);
    display: none;
    padding: 0 16px
}

.sidebar--footer .lang-area {
    align-items: center;
    display: flex;
    width: 100%
}

.sidebar--footer .lang-area .lang-area_holder {
    height: auto;
    margin-left: auto;
    padding: 0
}

.sidebar--footer .lang-area .lang-area_holder:after {
    display: none
}

.sidebar--footer .lang-area select {
    -webkit-appearance: none;
    -moz-appearance: none;
    background: #0000;
    border: none;
    color: var(--text-color-1);
    outline: none;
    padding: 0;
    text-align-last: right;
    text-indent: 1px;
    text-transform: uppercase;
    width: 30px
}

.sidebar--footer .lang-area .mob-lang-arrow {
    align-items: center;
    line-height: 1.5;
    margin: 17px 0;
    position: relative
}

.sidebar--footer .lang-area .mob-lang-arrow:before {
    color: var(--text-color-2);
    font-size: 24px;
    pointer-events: none;
    position: absolute;
    right: 0;
    top: 5px
}

.sidebar--footer .lang-area .tb--select-overlap {
    color: var(--text-color-2);
    font-size: 12px;
    height: 36px;
    line-height: 36px
